#!/usr/bin/env python3
"""make_unit_v4.py L - writes uc_unitd<W>.v and uc_unite<W>.v (ledger #1372).
uc_unitd<W> = uc_unitp<W> with the DECODED instruction flags (is_lui .. bad, 21 of them) held in registers, loaded in S_FETCH from imem_data at the same edge as `ir`, instead of
being decoded from `ir` through a deep chain of LUTs every clock (the start of the critical path in #1371).  The flags have the same value as the old combinational decode of `ir`
at every clock (reset value = decode of 0), so behaviour and clock counts do not change.  uc_unite<W> = the same unit inside the word-RAM wrapper of make_unit_v3.py (uc_unitr<W>).
Needs uc_unitp<W>.v and uc_unitr<W>.v (make_unit_v2.py / make_unit_v3.py).  Usage: python3 make_unit_v4.py 2 | 3 | 4"""
import os, re, subprocess, sys
L = int(sys.argv[1]); W = 1 << L; HERE = os.path.dirname(os.path.abspath(__file__))
subprocess.run([sys.executable, os.path.join(HERE, 'make_unit_v3.py'), str(L)], check=True, stdout=subprocess.DEVNULL)
s = open(os.path.join(HERE, 'uc_unitp%d.v' % W)).read()
names = ['is_lui', 'is_auipc', 'is_jal', 'is_jalr', 'is_br', 'is_ld', 'is_st', 'is_opi', 'is_op', 'is_sys', 'sh_i', 'sh_r', 'is_shift', 'is_sll', 'is_sra', 'is_cmp', 'is_slt', 'is_logic', 'is_sub', 'use_rb', 'bad']
NF = len(names)
a = s.index('    wire is_lui   = opc == 7\'b0110111;'); b = s.index('    wire [31:0] imm_i')
c = s.index('    wire sh_i     = '); d = s.index('    // ------------------------------------------------------------ digit select')
blk1, mid, blk2 = s[a:b], s[b:c], s[c:d]
assert 'wire is_sys' in blk1 and 'wire bad' in blk2 and 'wire use_rb' in blk2
dec_mod = 'module sc_decode%d (input [31:0] x, output [%d:0] o);\n    wire [6:0] opc = x[6:0]; wire [2:0] f3 = x[14:12]; wire [6:0] f7 = x[31:25];\n' % (W, NF - 1) + blk1 + blk2 + \
          '    assign o = {' + ', '.join(reversed(names)) + '};\nendmodule\n'
assigns = ''.join('    wire %s = dec_q[%d];\n' % (n, i) for i, n in enumerate(names))
regs = ('    // registered decode (make_unit_v4.py): same value as the decode of ir at every clock; loaded with ir in S_FETCH\n'
        '    wire [%d:0] dec_n, dec_z; reg [%d:0] dec_q;\n    sc_decode%d dn (.x(imem_data), .o(dec_n));\n    sc_decode%d dz (.x(32\'d0), .o(dec_z));\n'
        '    always @(posedge clk) begin if (rst) dec_q <= dec_z; else if (state == S_FETCH) dec_q <= dec_n; end\n' % (NF - 1, NF - 1, W, W))
# the imm wires use is_* and come after; keep them (mid) as they are
s = s[:a] + regs + assigns + mid + s[d:]
i = s.index('\nmodule sc_lane'); s = s[:i] + '\n' + dec_mod + s[i:]
s = s.replace('module uc_unitp%d #(' % W, 'module uc_unitd%d #(' % W, 1)
s = '// uc_unitd%d.v (GENERATED by make_unit_v4.py %d from uc_unitp%d.v, do not edit): decoded instruction flags registered (ledger #1372); same clock counts.\n' % (W, L, W) + s
open(os.path.join(HERE, 'uc_unitd%d.v' % W), 'w').write(s)
# the wrapper around it, self-contained (wrapper modules + the unit), module name uc_unite<W>
r = open(os.path.join(HERE, 'uc_unitr%d.v' % W)).read()
r = r.replace('module uc_unitr%d (' % W, 'module uc_unite%d (' % W, 1).replace('uc_unitp%d core' % W, 'uc_unitd%d core' % W, 1)
r = re.sub(r'^// uc_unitr%d.v.*\n' % W, '// uc_unite%d.v (GENERATED by make_unit_v4.py %d, do not edit): uc_unitr%d with the registered-decode unit uc_unitd%d inside (ledger #1372).  Needs uc_unitd%d.v.\n' % (W, L, W, W, W), r, count=1)
open(os.path.join(HERE, 'uc_unite%d.v' % W), 'w').write(r)
print('wrote uc_unitd%d.v and uc_unite%d.v' % (W, W))
